function def = f90_xaero03_definition()
%F90_XAERO03_DEFINITION Nonlinear single-engine fighter flight task.
%
% The exact open-loop source has a complete R2025a causal and 13-output
% waveform profile.  Finite actuators and closed-loop guidance in this
% task are independently authored rather than copied from that harness.

def = struct;
def.id = "XAERO03";
def.formal_id = "F90-XAERO-03";
def.current_status = "CURRENT";
def.status_target = "CURRENT";
def.workflow = "C";
def.design_revision = "current-design";
def.application_domain = ...
    "nonlinear fixed-wing flight dynamics, actuation and trajectory control";
def.physical_domains = [ ...
    "six-degree-of-freedom rigid-body flight", ...
    "altitude-dependent atmosphere and relative-wind air data", ...
    "nonlinear aerodynamic forces and moments", ...
    "bounded finite-rate propulsion and control-surface actuation"];
def.capability_types = [ ...
    "nonlinear plant construction", ...
    "near-trim initialization", ...
    "closed-loop altitude, airspeed and heading regulation", ...
    "crosswind-gust rejection"];
def.sim = struct("step",0.01,"stop",30.0);

def.public_constants = struct( ...
    "mass_kg",9295.438666, ...
    "reference_area_m2",27.870912, ...
    "wing_span_m",9.144, ...
    "mean_aerodynamic_chord_m",3.450336, ...
    "inertia_kg_m2",[ ...
        12874.844646 0 1331.412957; ...
        0 75673.607738 0; ...
        1331.412957 0 85552.095321], ...
    "gravity_m_per_s2",9.806, ...
    "initial_altitude_limits_m",[1550 9350], ...
    "initial_airspeed_limits_m_per_s",[95 260], ...
    "gust_duration_s",1.5, ...
    "thrust_limits_N",[4448.22 84516.18], ...
    "elevator_limit_rad",0.436332313, ...
    "aileron_limit_rad",0.375245789, ...
    "rudder_limit_rad",0.523598776, ...
    "leading_edge_flap_limits_rad",[0 0.436332313], ...
    "thrust_rate_limit_N_per_s",44482.2, ...
    "elevator_rate_limit_rad_per_s",1.047197551, ...
    "aileron_rate_limit_rad_per_s",1.396263402, ...
    "rudder_rate_limit_rad_per_s",2.094395102, ...
    "leading_edge_flap_rate_limit_rad_per_s",0.436332313, ...
    "angle_of_attack_limits_rad",[-0.34906585 0.785398163], ...
    "sideslip_limit_rad",0.523598776);

def.public_inputs = [ ...
    pin("altitude_reference",3048,1900,9000,"m", ...
        "commanded altitude above mean sea level"), ...
    pin("airspeed_reference",150,125,230,"m/s", ...
        "commanded true airspeed"), ...
    pin("heading_change",0.30,-0.65,0.65,"rad", ...
        "commanded heading change from the initial northward heading"), ...
    pin("initial_altitude_offset",-120,-350,350,"m", ...
        "initial altitude minus altitude_reference"), ...
    pin("initial_airspeed_offset",-10,-30,30,"m/s", ...
        "initial true airspeed minus airspeed_reference"), ...
    pin("command_time",4.0,3.0,7.0,"s", ...
        "time at which the heading-change command is applied"), ...
    pin("gust_speed",12,0,25,"m/s", ...
        "magnitude of the horizontal 1.5 s wind gust"), ...
    pin("gust_heading",90,-180,180,"deg", ...
        "horizontal gust direction clockwise from north"), ...
    pin("gust_time",9.0,6.0,13.0,"s", ...
        "start time of the horizontal gust")];

def.outputs = [ ...
    pout("flight_state",15, ...
        "[north, east, altitude, north/east/down inertial velocity, true airspeed, angle of attack, sideslip, roll, pitch, yaw, body p, q, r]", ...
        "[m,m,m,m/s x3,m/s,rad,rad,rad,rad,rad,rad/s x3]", ...
        "actual twelve-state rigid-body motion and air-relative state"), ...
    pout("air_data",6, ...
        "[air density, dynamic pressure, Mach number, applied gust north/east/down]", ...
        "[kg/m^3,Pa,1,m/s x3]", ...
        "atmosphere, relative-wind and actually applied disturbance data"), ...
    pout("actuation",10, ...
        "[commanded thrust/elevator/aileron/rudder/leading-edge flap, actual thrust/elevator/aileron/rudder/leading-edge flap]", ...
        "[N,rad x4,N,rad x4]", ...
        "controller requests and finite-rate physical actuator outputs"), ...
    pout("force_moment",12, ...
        "[aerodynamic body force xyz, aerodynamic body moment xyz, total body force xyz including thrust and gravity, total body moment xyz]", ...
        "[N x3,N*m x3,N x3,N*m x3]", ...
        "forces and moments that drive the same rigid-body state")];

def.prompt = strjoin([ ...
    "Build a nonlinear single-engine fighter-aircraft simulation with twelve-state six-degree-of-freedom rigid-body dynamics. Use a north-east-down inertial frame, report altitude as minus inertial down position, and use standard body axes x forward, y right, z down. Attitude is the 3-2-1 yaw-pitch-roll orientation from body to inertial coordinates; p, q, and r are body angular rates, not Euler-angle derivatives. The minimum topology is a finite-mass/inertia rigid body; altitude-dependent atmosphere; relative-wind air-data calculation; nonlinear aerodynamic force and moment dependence on angle of attack, sideslip, body rates and actual control surfaces; gravity and thrust; five finite-response actuators; and a feedback controller. Directly prescribing the aircraft state or replaying a trajectory is not valid.", ...
    "Read altitude_reference, airspeed_reference, heading_change, initial_altitude_offset, initial_airspeed_offset, command_time, gust_speed, gust_heading, and gust_time from base-workspace variables. Nominal values are 3048 m, 150 m/s, 0.30 rad, -120 m, -10 m/s, 4.0 s, 12 m/s, 90 deg, and 9.0 s. Their operating ranges are respectively 1900--9000 m, 125--230 m/s, -0.65--0.65 rad, -350--350 m, -30--30 m/s, 3--7 s, 0--25 m/s, -180--180 deg, and 6--13 s. These ranges make every allowed initial altitude 1550--9350 m and every allowed initial airspeed 95--260 m/s. Initialize near a physically plausible steady-flight condition at the requested initial altitude and airspeed. Apply heading_change at command_time. gust_heading is clockwise from north and defines an actual horizontal air-mass velocity in the north-east-down frame. Apply that velocity for 1.5 s beginning at gust_time. Compute relative air velocity as ground velocity minus this gust vector before transforming it into body axes; air_data must log this same applied NED vector. The gust must enter the relative-wind aerodynamics rather than only a log.", ...
    "Use mass 9295.438666 kg, reference area 27.870912 m^2, span 9.144 m, mean aerodynamic chord 3.450336 m, and inertia matrix [12874.844646 0 1331.412957; 0 75673.607738 0; 1331.412957 0 85552.095321] kg*m^2. The nonlinear aerodynamic representation may use tables or smooth coefficient surfaces; its internal coordinates and control design are not prescribed, but forces and moments must vary causally with dynamic pressure, angle of attack, sideslip, rates and actual surface deflections.", ...
    "Bound thrust to 4448.22--84516.18 N, elevator to +/-0.436332313 rad, aileron to +/-0.375245789 rad, rudder to +/-0.523598776 rad, and leading-edge flap to 0--0.436332313 rad. Limit their rates respectively to 44482.2 N/s, 1.047197551 rad/s, 1.396263402 rad/s, 2.094395102 rad/s, and 0.436332313 rad/s. Across the declared range, regulate altitude, true airspeed and heading, keep sideslip controlled, remain inside angle-of-attack -0.34906585--0.785398163 rad and sideslip +/-0.523598776 rad, and recover useful regulation after the gust. The trim, guidance, control allocation and actuator dynamics methods are not prescribed.", ...
    "Log four Timeseries named flight_state, air_data, actuation, and force_moment. flight_state has 15 channels [north, east, altitude, north/east/down inertial velocity, true airspeed, angle of attack, sideslip, roll, pitch, yaw, body p, q, r]. air_data has 6 channels [air density, dynamic pressure, Mach number, applied gust north/east/down]. actuation has 10 channels [commanded thrust/elevator/aileron/rudder/leading-edge flap, then the corresponding five actual actuator outputs]. force_moment has 12 channels [aerodynamic body force xyz, aerodynamic body moment xyz, total body force xyz including thrust and gravity, total body moment xyz]. All logs must come from one causal flight simulation and the reported actual actuators and loads must be the quantities used by the rigid-body plant.", ...
    "Work directly in the required model file and keep the latest usable state saved at that path throughout the task."], ...
    sprintf("\n\n"));

def.scenarios = [ ...
    scenario("high_altitude_fast_right_turn", ...
        values(8800,225,0.58,-300,-25,3.5,22,110,7.0)), ...
    scenario("low_altitude_slow_left_turn", ...
        values(1950,125,-0.58,250,25,5.5,18,-70,11.5)), ...
    scenario("large_climb_transition", ...
        values(6200,180,0.20,-340,-18,4.5,15,160,8.5)), ...
    scenario("gust_pair_none", ...
        values(4500,165,0.40,-100,-8,4.0,0,35,8.0)), ...
    scenario("gust_pair_crosswind", ...
        values(4500,165,0.40,-100,-8,4.0,24,35,8.0)), ...
    scenario("heading_pair_left", ...
        values(3200,140,-0.55,0,0,3.0,8,90,12.5)), ...
    scenario("heading_pair_right", ...
        values(3200,140,0.55,0,0,3.0,8,90,12.5)), ...
    scenario("joint_boundary", ...
        values(9000,125,-0.62,300,28,6.8,24.5,-145,7.2))];

def.range_scenario_ids = [ ...
    "nominal","high_altitude_fast_right_turn", ...
    "low_altitude_slow_left_turn","large_climb_transition", ...
    "joint_boundary"];
def.mixed_stress_scenario_ids = "joint_boundary";
def.trim_release_scenario_ids = [ ...
    "heading_pair_left","heading_pair_right"];
def.paired_scenarios = struct( ...
    "gust",["gust_pair_none","gust_pair_crosswind"], ...
    "heading",["heading_pair_left","heading_pair_right"]);

def.groups = struct( ...
    "G","load, update, compile, all official simulations, output contract, finite values and broad flight domains", ...
    "A","nominal altitude, airspeed, heading and sideslip regulation", ...
    "Q","flight-envelope, actuator-position/rate, saturation and load quality", ...
    "M","air-data, kinematic, translational, rotational, actuator and nonlinear aerodynamic causal closure", ...
    "R","worst altitude, speed and maneuver tracking, including the mixed joint stress condition", ...
    "D","zero-offset trim release, paired heading response, true gust response and recovery", ...
    "weights",struct("A",0.20,"Q",0.12,"M",0.34,"R",0.18,"D",0.16));

def.source = struct( ...
    "slot_mapping","AERO-05/SRC-F16-TEST", ...
    "repository","https://github.com/isrlab/F16-Model-Matlab", ...
    "revision","d019742f2fe7f5f25c521bc7e846519b28b759b3", ...
    "model","F16Testing.slx", ...
    "model_file_presence","present", ...
    "license","MIT", ...
    "screen_evidence","not_redistributed", ...
    "waveform_profile","not_redistributed", ...
    "waveform_profile_file_presence","present", ...
    "setup_command","conversion; Param=load_F16_params(); h0=-10000*ft2m; Vt0=300*ft2m; IC.inertial_position=[0,0,h0]; IC.body_velocity=[Vt0,0,0]; IC.euler_angles=[0,0,0]*d2r; IC.omega=[0,0,0]; x0=[IC.inertial_position,IC.euler_angles,IC.body_velocity,IC.omega]; u0=[9000*lbf2N,0,0,0,0,0,0]; Tend=5;", ...
    "source_harness_character","open-loop constant-input nonlinear plant test; no finite actuator or feedback controller in the exact source harness", ...
    "use","mechanism, envelope and scale audit; the benchmark controller and actuator dynamics are independently authored");
def.runner = struct( ...
    "builder","scripts/formal90/tasks/f90_xaero03/f90_xaero03_build_reference.m", ...
    "evidence_extractor_and_runner","scripts/formal90/tasks/f90_xaero03/f90_xaero03_extract_candidate_evidence.m", ...
    "scoring_implementation","f90_xaero03_scoring", ...
    "reference_model","reference/files/XAERO03_reference.slx", ...
    "public_spec","public_spec.json", ...
    "official_scenarios","official_scenarios.json");
def.reference_configuration = struct( ...
    "configuration","tuned_reference", ...
    "model_path","reference/files/XAERO03_reference.slx", ...
    "model_file_presence","present", ...
    "altitude_gain",.001058, ...
    "down_gain",.0228, ...
    "elevator_p",1.4725, ...
    "elevator_d",.741, ...
    "speed_gain",2208, ...
    "additional_adjustment_enabled",false);
end

function x = pin(name,nominal,minv,maxv,unit,meaning)
x = struct("name",name,"nominal",nominal,"min",minv,"max",maxv, ...
    "unit",unit,"meaning",meaning);
end

function x = pout(name,channels,order,unit,source)
x = struct("name",name,"channels",channels,"order",order, ...
    "unit",unit,"physical_source",source);
end

function x = scenario(id,v)
x = struct("id",id,"values",v);
end

function v = values(altitude,airspeed,heading,altitudeOffset, ...
        airspeedOffset,commandTime,gustSpeed,gustHeading,gustTime)
v = struct( ...
    "altitude_reference",altitude, ...
    "airspeed_reference",airspeed, ...
    "heading_change",heading, ...
    "initial_altitude_offset",altitudeOffset, ...
    "initial_airspeed_offset",airspeedOffset, ...
    "command_time",commandTime, ...
    "gust_speed",gustSpeed, ...
    "gust_heading",gustHeading, ...
    "gust_time",gustTime);
end
